-- add-column /TRDEMOFIN/COMPANIES.REGION (CHAR(80)) via /TRBASE/ADDRESS
ALTER TABLE "/TRDEMOFIN/COMPANIES" ADD COLUMN "REGION" TEXT CONSTRAINT "/TRDEMOFIN/COMPANIES#CK#REGION" CHECK ("REGION" IS NULL OR (length("REGION") <= 80));

